#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

int set_iface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char *path = NULL;
    FILE *fp;
    int ret = -1;

    if (!iface || !var || !name) {
        return -1;
    }

    path = malloc(snprintf(NULL, 0, var, iface) + 1);
    if (!path) {
        return -1;
    }

    snprintf(path, snprintf(NULL, 0, var, iface) + 1, var, iface);

    if (access(path, F_OK) == -1) {
        free(path);
        return -1;
    }

    fp = fopen(path, "w");
    if (!fp) {
        free(path);
        return -1;
    }

    if (fprintf(fp, "%u\n", val) < 0) {
        goto error;
    }

    if (fclose(fp) != 0) {
        goto error;
    }

    ret = 0;

error:
    if (ret != 0) {
        // Log error message
        fprintf(stderr, "Failed to write %s (%u) to %s: %s\n", name, val, path, strerror(errno));
    }

    free(path);
    return ret;
}

