#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

int set_interface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char *path = NULL;
    FILE *file = NULL;
    int result = -1;

    if (!iface || !var || !name) {
        return -1;
    }

    if (asprintf(&path, var, iface) == -1) {
        goto cleanup;
    }

    if (access(path, F_OK) != 0) {
        goto cleanup;
    }

    file = fopen(path, "w");
    if (!file) {
        goto cleanup;
    }

    if (fprintf(file, "%u\n", val) < 0) {
        goto cleanup;
    }

    result = 0;

cleanup:
    if (file) {
        fclose(file);
    }
    if (path) {
        free(path);
    }

    if (result < 0) {
        // Log error using standard error stream as no specific logging function is provided
        fprintf(stderr, "Failed to set %s for interface %s: %s\n", name, iface, strerror(errno));
    }

    return result;
}

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

int set_interface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char path[256];
    snprintf(path, sizeof(path), var, iface);

    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror("Failed to verify file existence");
        return -1;
    }
    fclose(fp);

    fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to open file for writing");
        return -1;
    }

    if (fprintf(fp, "%u\n", val) < 0) {
        perror("Failed to write value to file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Failed to close file");
        return -1;
    }

    return 0;
}
